<?php
require_once __DIR__.'/config/config.php'; require_login();
$pageTitle='Gastos'; $active='gastos';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$concepto=trim($_POST['concepto']??'');$valor=(float)($_POST['valor']??0);$fecha=$_POST['fecha']??date('Y-m-d');if($concepto===''||$valor<=0)throw new RuntimeException('Ingresa un concepto y un valor mayor que cero.');db()->prepare('INSERT INTO gastos(usuario_id,concepto,categoria,valor,fecha,observaciones) VALUES(?,?,?,?,?,?)')->execute([$_SESSION['user_id'],$concepto,trim($_POST['categoria']??''),$valor,$fecha,trim($_POST['observaciones']??'')]);$success='Gasto registrado.';}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'No se pudo registrar el gasto.';}}
$rows=[];$total=0;try{$rows=db()->query('SELECT g.*,u.nombre usuario FROM gastos g JOIN usuarios u ON u.id=g.usuario_id ORDER BY g.fecha DESC,g.id DESC LIMIT 300')->fetchAll();$total=(float)db()->query('SELECT COALESCE(SUM(valor),0) FROM gastos WHERE MONTH(fecha)=MONTH(CURDATE()) AND YEAR(fecha)=YEAR(CURDATE())')->fetchColumn();}catch(Throwable $ex){}
include __DIR__.'/includes/header.php';
?>
<?php if($error): ?><div class="notice danger"><?=e($error)?></div><?php endif;if($success): ?><div class="notice success"><?=e($success)?></div><?php endif; ?>
<div class="stats-grid"><div class="stat-card"><div class="stat-icon">▧</div><div><div class="stat-label">GASTOS DEL MES</div><div class="stat-value"><?=money($total)?></div></div></div></div>
<section class="form-panel"><h2>Registrar gasto</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Concepto<input name="concepto" required></label><label>Categoría<input name="categoria" placeholder="Arriendo, servicios, transporte..."></label><label>Valor<input type="number" name="valor" min=".01" step=".01" required></label><label>Fecha<input type="date" name="fecha" value="<?=date('Y-m-d')?>" required></label></div><label class="block-label">Observaciones<textarea name="observaciones" rows="2"></textarea></label><button class="btn primary">Guardar gasto</button></form></section>
<section class="table-panel"><div class="table-toolbar"><b>Historial de gastos</b><input class="quick-search" placeholder="Buscar gasto..." data-table-search="expenses-table"></div><div class="table-scroll"><table id="expenses-table"><thead><tr><th>Fecha</th><th>Concepto</th><th>Categoría</th><th>Registrado por</th><th class="numeric">Valor</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e(date('d/m/Y',strtotime($r['fecha'])))?></td><td><b><?=e($r['concepto'])?></b></td><td><?=e($r['categoria'])?></td><td><?=e($r['usuario'])?></td><td class="numeric"><?=money($r['valor'])?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="5" class="empty">No hay gastos registrados.</td></tr><?php endif; ?></tbody></table></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
